mapper.update:
UPDATE lifecycle_outbox SET status = 'in_flight', lease_owner = #{owner},
  locked_until = #{leaseUntil,jdbcType=TIMESTAMP}, attempts = attempts + 1, updated_at = CURRENT_TIMESTAMP
WHERE message_id = #{messageId}

UPDATE lifecycle_outbox SET status = 'succeeded', lease_owner = NULL,
  locked_until = NULL, last_error = NULL, updated_at = CURRENT_TIMESTAMP
WHERE message_id = #{messageId} AND status = 'in_flight' AND lease_owner = #{owner}

UPDATE lifecycle_outbox SET status = 'failed', available_at = #{nextAttemptAt,jdbcType=TIMESTAMP},
  lease_owner = NULL, locked_until = NULL, last_error = #{error,jdbcType=VARCHAR}, updated_at = CURRENT_TIMESTAMP
WHERE message_id = #{messageId} AND status = 'in_flight' AND lease_owner = #{owner}
